CREATE TABLE `sessions` (`id` CHAR(36) NOT NULL,`org_id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`token_hash` CHAR(64) NOT NULL,`expires_at` DATETIME(3) NOT NULL,`revoked_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`last_seen_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `sessions_org_id_user_id_revoked_at_idx` (`org_id`,`user_id`,`revoked_at`),CONSTRAINT `sessions_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `sessions_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `password_reset_tokens` (`id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`token_hash` CHAR(64) NOT NULL,`expires_at` DATETIME(3) NOT NULL,`used_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `password_reset_tokens_token_hash_key` (`token_hash`),INDEX `password_reset_tokens_user_id_expires_at_idx` (`user_id`,`expires_at`),CONSTRAINT `password_reset_tokens_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `notifications` (`id` CHAR(36) NOT NULL,`org_id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`type` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`body` VARCHAR(191) NULL,`resource_type` ENUM('FILE','FOLDER') NULL,`resource_id` CHAR(36) NULL,`read_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `notifications_org_id_user_id_read_at_created_at_idx` (`org_id`,`user_id`,`read_at`,`created_at`),CONSTRAINT `notifications_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `notifications_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `comments` (`id` CHAR(36) NOT NULL,`org_id` CHAR(36) NOT NULL,`file_id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`parent_id` CHAR(36) NULL,`body` TEXT NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `comments_org_id_file_id_created_at_idx` (`org_id`,`file_id`,`created_at`),INDEX `comments_user_id_idx` (`user_id`),CONSTRAINT `comments_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `comments_file_id_fkey` FOREIGN KEY (`file_id`) REFERENCES `files` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `comments_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `comments_parent_id_fkey` FOREIGN KEY (`parent_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `storage_quotas` (`id` CHAR(36) NOT NULL,`org_id` CHAR(36) NOT NULL,`quota_bytes` BIGINT NOT NULL,`used_bytes` BIGINT NOT NULL DEFAULT 0,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `storage_quotas_org_id_key` (`org_id`),CONSTRAINT `storage_quotas_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
